class Solution {
public:
    int minCost(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<int> vals;
        vals.reserve((size_t)m * n);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                vals.push_back(grid[i][j]);
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int U = vals.size();

        vector<vector<int>> rk(m, vector<int>(n));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                rk[i][j] = lower_bound(vals.begin(), vals.end(), grid[i][j]) - vals.begin();

        const int INF = INT_MAX / 2;
        vector<vector<int>> dp(m, vector<int>(n, INF));
        dp[0][0] = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                int b = INF;
                if (i > 0) b = min(b, dp[i - 1][j]);
                if (j > 0) b = min(b, dp[i][j - 1]);
                dp[i][j] = b + grid[i][j];
            }
        }

        for (int t = 1; t <= k; t++) {
            vector<int> mn(U, INF);
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    mn[rk[i][j]] = min(mn[rk[i][j]], dp[i][j]);
            for (int r = U - 2; r >= 0; r--)
                mn[r] = min(mn[r], mn[r + 1]);

            vector<vector<int>> nd(m, vector<int>(n));
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    nd[i][j] = min(dp[i][j], mn[rk[i][j]]);

            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == 0 && j == 0) continue;
                    int b = INF;
                    if (i > 0) b = min(b, nd[i - 1][j]);
                    if (j > 0) b = min(b, nd[i][j - 1]);
                    nd[i][j] = min(nd[i][j], b + grid[i][j]);
                }
            }
            dp = move(nd);
        }
        return dp[m - 1][n - 1];
    }
};
